using Microsoft.AspNetCore.Mvc;using Microsoft.IdentityModel.Tokens;using System.IdentityModel.Tokens.Jwt;using System.Security.Claims;using System.Text;using NutriPlate.Api.DTOs;using NutriPlate.Api.Services;using NutriPlate.Api.Models;using Microsoft.Extensions.Options;using NutriPlate.Api.Configuration;
namespace NutriPlate.Api.Controllers;
[ApiController][Route("api/auth")]
public class AuthController(NutriPlateService service,IConfiguration config):ControllerBase {
 [HttpPost("register")] public async Task<IActionResult> Register(RegisterRequest req,CancellationToken ct){var user=await service.Register(req.Email,req.Password,req.DisplayName,ct);return Ok(new{token=Token(user),user=new{id=user.Id,email=user.Email,displayName=user.DisplayName}});}
 [HttpPost("login")] public async Task<IActionResult> Login(LoginRequest req,CancellationToken ct){var user=await service.FindUser(req.Email,ct);if(user==null||!service.VerifyPassword(user,req.Password))return Unauthorized(new{error="Invalid email or password."});return Ok(new{token=Token(user),user=new{id=user.Id,email=user.Email,displayName=user.DisplayName}});}
 private string Token(AppUser user){var key=config["Jwt:Key"]??"";if(key.Length<32)throw new InvalidOperationException("JWT configuration is missing or too short. Set Jwt__Key to a private value of at least 32 characters.");var issuer=config["Jwt:Issuer"]??"NutriPlate.Api";var audience=config["Jwt:Audience"]??"NutriPlate.Client";var claims=new[]{new Claim(ClaimTypes.NameIdentifier,user.Id!),new Claim(ClaimTypes.Email,user.Email),new Claim(ClaimTypes.Name,user.DisplayName)};var creds=new SigningCredentials(new SymmetricSecurityKey(Encoding.UTF8.GetBytes(key)),SecurityAlgorithms.HmacSha256);return new JwtSecurityTokenHandler().WriteToken(new JwtSecurityToken(issuer,audience,claims,expires:DateTime.UtcNow.AddHours(4),signingCredentials:creds));}
}
